for r,c,v in [(5,1,9),(7,3,2),(8,2,2),(8,4,2),(9,3,2),(9,6,5),(10,5,5),(10,7,5),(11,4,5),(11,8,5),(11,13,8),(12,3,5),(12,9,5),(13,4,5),(13,8,5),(14,5,5),(14,7,5),(15,6,5),(15,13,8)]: test[r][c]=v

def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    for color,delta in [(2,-1),(5,1)]:
        cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if not cells: continue
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        radius=(max(rs)-min(rs))//2
        cr=(max(rs)+min(rs))//2; cc=(max(cs)+min(cs))//2
        for r,c in cells: out[r][c]=7
        nr=radius+delta
        if nr==0:
            out[cr][cc]=color
        else:
            for r in range(h):
                for c in range(w):
                    if abs(r-cr)+abs(c-cc)==nr: out[r][c]=color
    return out
ans=transform(test)
for row in ans: print(' '.join(map(str,row)))

